from robot.api import logger
from functools import wraps
from datetime import datetime, timedelta
from taf.rfrl.cbts.connections.conn_netact import GenericNetAct

LOG_HEAD = LOG_END = '*' * 8


def connect_disconnect_netact_by_taf(service_name=None):
    def connect_disconnect_netact(netact_fun):
        @wraps(netact_fun)
        def wrapper(netact_ope_instance, *args, **kwargs):
            if not netact_ope_instance.selected:
                netact_ope_instance.select_available_netact(netact_index=kwargs.get('netact_index'))

            netact_ope_instance.setup_netact_by_taf(service_name)
            try:
                result = netact_fun(netact_ope_instance, *args, **kwargs)
                return result
            finally:
                netact_ope_instance.cleanup_netact_by_taf(service_name)

        return wrapper

    return connect_disconnect_netact

