class NetactOperations(GenericNetAct):
    SUPPORTED_MR = {
        'fhgw': 'MRC-AICTAFHGW/MR-',
        'vdu': 'MRC-AICTAVDU/MR-',
        'vcu': 'MRC-AICTAVCU/MR-'
    }

    SUPPORTED_NETACT_MO_RELEASE = {
        '0.300': '24R2VDU',
        '0.250': '24R2VCU',
        '21.300': '24R1VDU',
        '21.250': '24R1VCU',
        '20.300': '23R4VDU',
        '20.250': '23R4VCU'
    }

    @connect_disconnect_netact_by_taf(service_name='fmwas')
    def get_all_alarms(self, mrbts_name, netact_index=None):
        dist_name = 'PLMN-PLMN' + '/' + mrbts_name
        alarm_list = self.netact_taf.get_alarms(dist_name=dist_name)
        return alarm_list

    @connect_disconnect_netact_by_taf(service_name='fmwas')
    def upload_alarms_from_netact(self, mrbts_name, netact_index=None):
        dist_name = 'PLMN-PLMN' + '/' + mrbts_name
        res = self.netact_taf.upload_alarms(dist_name=dist_name)
        return res

    @connect_disconnect_netact_by_taf(service_name='cmwas')
    def integrate_fhgw_to_netact(self, ne_id, ne_release, ne_address, security_mode='no TLS', netact_index=None):
        mr = NetactOperations.SUPPORTED_MR['fhgw'] + ne_id
        dn = 'PLMN-PLMN/' + ne_id
        ip_version = 'IPV6' if ':' in ne_address else 'IPV4'

        logger.info('{} Start To Integrate FHGW {} {} {}'.format(LOG_HEAD, dn, ne_address, LOG_END))

        self.netact_taf.integrate_fhgw_with_netact(release=ne_release, mr=mr,
                                                   fhgw_address=ne_address, dist_name=dn,
                                                   security_mode=security_mode, ip_version=ip_version)

    @connect_disconnect_netact_by_taf(service_name='cmwas')
    def integrate_vdu_to_netact(self, ne_id, ne_release, ne_address, security_mode='no TLS', netact_index=None):
        mr = NetactOperations.SUPPORTED_MR['vdu'] + ne_id.split('-')[1]
        dn = 'PLMN-PLMN/' + ne_id
        ip_version = 'IPV6' if ':' in ne_address else 'IPV4'
        netact_mo_release = ne_release + "VDU"
        logger.info('{} Start To Integrate VDU {} {} {}'.format(LOG_HEAD, dn, ne_address, LOG_END))

        self.netact_taf.integrate_mrbts_with_netact(release=netact_mo_release, mr=mr,
                                                    mrbts_address=ne_address, dist_name=dn,
                                                    security_mode=security_mode, ip_version=ip_version)

    @connect_disconnect_netact_by_taf(service_name='cmwas')
    def integrate_vcu_to_netact(self, ne_id, ne_release, ne_address, security_mode='no TLS', netact_index=None):
        mr = NetactOperations.SUPPORTED_MR['vcu'] + ne_id.split('-')[1]
        dn = 'PLMN-PLMN/' + ne_id
        ip_version = 'IPV6' if ':' in ne_address else 'IPV4'
        netact_mo_release = ne_release + "VCU"
        logger.info('{} Start To Integrate VCU {} {} {}'.format(LOG_HEAD, dn, ne_address, LOG_END))

        self.netact_taf.integrate_mrbts_with_netact(release=netact_mo_release, mr=mr,
                                                    mrbts_address=ne_address, dist_name=dn,
                                                    security_mode=security_mode, ip_version=ip_version)

